import clone from 'rfdc';
import { REDUCER_ACTION_TYPE } from '../../constant';
/**
 * findDesignValueById
 * @description 递归查找设计值中指定id的设计值
 * @param {string} id
 * @param {DesignValue} designValue
 * @return {DesignValue | undefined}
 */
export function findDesignValueById(id, designValue) {
  if (designValue.id === id) {
    return designValue;
  }
  if (designValue.props.children) {
    for (var i = 0; i < designValue.props.children.length; i++) {
      var child = designValue.props.children[i];
      var result = findDesignValueById(id, child);
      if (result) {
        return result;
      }
    }
  }
}
/**
 * findDesignValueByIdToClone
 * @description 递归查找设计值中指定id的设计值的clone版本
 * @param {string} id
 * @param {DesignValue} designValue
 * @return {DesignValue | undefined}
 */
export function findDesignValueByIdToClone(id, designValue) {
  var _designValue = findDesignValueById(id, designValue);
  if (!!_designValue) {
    return clone()(_designValue);
  }
  return _designValue;
}
/**
 * reducer
 * @description 对设计值进行修改
 */
var reducer = function (state, action) {
  switch (action.type) {
    // 修改FormItem的props
    case REDUCER_ACTION_TYPE.updateFormItemProps:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.props.formItemProps = action.payload.props;
        }
        return state;
      }
    // 修改控件本身的props
    case REDUCER_ACTION_TYPE.updateFieldProps:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.props.fieldProps = action.payload.props;
        }
        return state;
      }
    // 修改控件样式的props
    case REDUCER_ACTION_TYPE.updateStyleProps:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.props.styleProps = action.payload.props;
        }
        return state;
      }
    // 修改控件Actions的props
    case REDUCER_ACTION_TYPE.updateActionsProps:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.props.actionsProps = action.payload.props;
        }
        return state;
      }
    // 修改控件children
    case REDUCER_ACTION_TYPE.updateChildrenProps:
      {
        var designValue = findDesignValueById(action.payload.id, state);
        if (designValue) {
          designValue.props.children = action.payload.props;
        }
        return state;
      }
    // 什么都不做
    default:
      return state;
  }
};
export default reducer;